      if (e.dead) {
        if (game.discardAllocatedEnemy) game.discardAllocatedEnemy(e);
        else {
          const dense = game.enemies.indexOf(e);
          if (dense >= 0) game.enemies.splice(dense, 1);
        }
        return e;
      }
      if (parent && hasLife) e.hp = life | 0;
      e.ecl.itemDrop = item;
      if (hasScore) e.score = score | 0;
