        moveMode: 0,
        interpKind: 0,
        interp: null,
        heading: 0,
        orbitAngle: 0,
        orbitAngularVelocity: 0,
        orbitSpeed: 0,
        orbitAcceleration: 0,
        orbitTarget: { x: 0, y: 0, z: 0 },
        orbitDuration: 0,
        orbitLeft: 0,
        bulletProps: null,
        bulletSfx: 0,
        bulletSfxInterval: 0,
